css:
@import url("https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&display=swap");
:root{--blue:#0B3D91;--blue-2:#1450B8;--sky:#E8F4FF;--sky-2:#CFE6FF;--sun:#FF9F1C;--grn:#17A673;--text:#16264A;--muted:#5A6A89;--line:#DCE6F2;
--font:"Sora",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1200px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font);font-size:17px;line-height:1.65;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-weight:800;margin:0;line-height:1.08;color:var(--blue);letter-spacing:-.03em}h3{font-weight:700;letter-spacing:-.01em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--sun);padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--sun);outline-offset:3px;border-radius:6px}
.site-header{position:sticky;top:0;z-index:40;background:rgba(255,255,255,.95);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;height:72px}
.logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:22px;text-decoration:none;color:var(--blue)}
.logo i{width:34px;height:22px;background:var(--blue);border-radius:12px;position:relative}.logo i::before{content:"";position:absolute;width:18px;height:18px;border-radius:50%;background:var(--blue);left:6px;top:-8px}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:600;font-size:16px}.menu a:hover{color:var(--blue-2)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:13px 24px;border-radius:12px;font-weight:700;text-decoration:none;border:2px solid transparent;font-family:var(--font);font-size:16px;cursor:pointer}
.btn-blue{background:var(--blue);color:#fff}.btn-blue:hover{background:var(--blue-2)}
.btn-sun{background:var(--sun);color:#1c1300}.btn-out{border-color:var(--blue);color:var(--blue)}
.burger{display:none;background:none;border:2px solid var(--line);border-radius:10px;padding:8px 10px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:var(--blue);margin:4px 0}
.hero{background:linear-gradient(180deg,var(--sky),#fff);padding:76px 0 60px}
.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:50px;align-items:center}
.pill{display:inline-block;background:#fff;border:1px solid var(--line);border-radius:999px;padding:6px 14px;font-size:14px;font-weight:600;margin-bottom:22px}
.pill b{color:var(--grn)}
.hero h1{font-size:clamp(40px,5.6vw,72px)}
.hero .lead{font-size:19px;color:var(--muted);max-width:44ch;margin:22px 0 28px}
.actions{display:flex;gap:12px;flex-wrap:wrap}
.perks{display:flex;gap:22px;flex-wrap:wrap;margin-top:28px;font-size:15px;font-weight:600;color:var(--muted);padding:0;list-style:none}.perks li::before{content:"✓ ";color:var(--grn)}
.calc{background:#fff;border:1px solid var(--line);border-radius:22px;padding:28px;box-shadow:0 40px 80px -45px rgba(11,61,145,.45)}
.calc h2{font-size:24px;margin-bottom:4px}.calc>p{color:var(--muted);font-size:15px}
.rng{margin:18px 0}
.rng label{display:flex;justify-content:space-between;font-weight:600;font-size:15px;margin-bottom:6px}
.rng output{color:var(--blue);font-weight:800}
input[type=range]{width:100%;accent-color:var(--blue)}
.calc select{width:100%;font:inherit;font-size:15px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;color:var(--text);background:#fff}
.total{display:flex;justify-content:space-between;align-items:end;border-top:1px solid var(--line);padding-top:18px;margin-top:22px}
.total b{font-size:44px;font-weight:800;color:var(--blue);line-height:1}.total small{color:var(--muted);font-size:14px}
.calc .btn{width:100%;margin-top:18px}
.ph{padding:40px 0;border-bottom:1px solid var(--line)}
.ph .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;text-align:center}
.ph b{font-size:34px;font-weight:800;color:var(--blue);display:block}.ph span{font-size:15px;color:var(--muted)}
section{padding:100px 0}
.head{text-align:center;max-width:760px;margin:0 auto 54px}.head h2{font-size:clamp(34px,4.4vw,56px)}.head p{color:var(--muted);font-size:18px;margin-top:14px}
.prods{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.prod{border:1px solid var(--line);border-radius:18px;padding:26px;background:#fff}
.prod .ic{width:48px;height:48px;border-radius:14px;background:var(--sky);color:var(--blue);display:grid;place-items:center;margin-bottom:16px}
.prod h3{font-size:19px;margin-bottom:6px}.prod p{margin:0 0 12px;color:var(--muted);font-size:15px}.prod .from{font-weight:700;font-size:15px;color:var(--blue)}
.regions{background:var(--blue);color:#CFE0FF}
.regions h2{color:#fff}.regions .head p{color:#A9C3F0}
.map{display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:center}
.map figure{margin:0;border-radius:22px;overflow:hidden;position:relative}
.map figure img{width:100%;aspect-ratio:16/10;object-fit:cover}
.map figure i{position:absolute;width:14px;height:14px;border-radius:50%;background:var(--sun);box-shadow:0 0 0 6px rgba(255,159,28,.3)}
.rlist{list-style:none;padding:0;margin:0}
.rlist li{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--blue-2);font-size:16px}
.rlist b{color:#fff}.rlist span{color:#9FE3C4;font-weight:600}
.feat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.feat{padding:6px 0}
.feat h3{font-size:20px;margin-bottom:8px}.feat p{margin:0;color:var(--muted);font-size:16px}
.feat b{display:inline-block;background:var(--sky);color:var(--blue);border-radius:8px;padding:2px 10px;font-size:13px;margin-bottom:12px}
.split{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center;margin-top:90px}
.split img{border-radius:22px;width:100%;aspect-ratio:4/3;object-fit:cover}
.split h2{font-size:clamp(30px,3.8vw,46px);margin-bottom:14px}.split p{color:var(--muted)}
.plans{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.plan{border:1px solid var(--line);border-radius:18px;padding:26px;display:flex;flex-direction:column;background:#fff}
.plan.hot{border:2px solid var(--blue);background:var(--sky)}
.plan h3{font-size:19px}.plan .amt{font-size:40px;font-weight:800;color:var(--blue);margin:10px 0 0}.plan .amt small{font-size:14px;font-weight:600;color:var(--muted)}
.plan ul{list-style:none;padding:0;margin:14px 0 22px;font-size:15px}.plan li{padding:6px 0;border-bottom:1px dashed var(--line)}
.plan .btn{margin-top:auto;padding:11px}
.pricing{background:#F7FAFE}
.note{text-align:center;color:var(--muted);font-size:15px;margin-top:20px}
.quotes{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}
.q{background:var(--sky);border-radius:20px;padding:30px;margin:0}
.q p{font-size:19px;color:var(--text)}.q cite{font-style:normal;font-weight:700;color:var(--blue)}.q cite span{display:block;font-weight:400;color:var(--muted);font-size:15px}
.faq{max-width:820px;margin:0 auto}
.faq details{border:1px solid var(--line);border-radius:14px;padding:18px 22px;margin-bottom:10px}
.faq summary{list-style:none;cursor:pointer;font-weight:700;font-size:18px;display:flex;justify-content:space-between;gap:18px;color:var(--blue)}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";font-size:24px;line-height:1;color:var(--sun)}
.faq details[open] summary::after{content:"−"}.faq details p{margin:10px 0 0;color:var(--muted)}
.cta{padding:0 0 90px}
.cta-box{background:var(--blue);border-radius:28px;padding:60px;text-align:center;color:#CFE0FF}
.cta-box h2{color:#fff;font-size:clamp(34px,4.6vw,58px)}.cta-box p{font-size:19px;margin:16px 0 26px}
.cta-box .btn-out{border-color:#fff;color:#fff}
footer{border-top:1px solid var(--line);padding:50px 0 28px;color:var(--muted);font-size:15px}
.foot{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:30px;margin-bottom:28px}
footer h3{font-size:15px;margin-bottom:12px}footer ul{list-style:none;padding:0;margin:0}footer li{margin-bottom:8px}footer a{text-decoration:none}footer a:hover{color:var(--blue)}
.legal{border-top:1px solid var(--line);padding-top:18px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
@media (max-width:1000px){.menu,.nav>.btn{display:none}.burger{display:block}
.menu.open{display:flex;flex-direction:column;position:absolute;top:72px;left:0;right:0;background:#fff;padding:22px;border-bottom:1px solid var(--line);gap:16px}
.hero-grid,.map,.split{grid-template-columns:1fr}.prods,.plans{grid-template-columns:1fr 1fr}.feat-grid{grid-template-columns:1fr 1fr}.ph .wrap{grid-template-columns:1fr 1fr}.foot{grid-template-columns:1fr 1fr}}
@media (max-width:600px){body{font-size:16px}section{padding:72px 0}.prods,.plans,.feat-grid,.quotes{grid-template-columns:1fr}.cta-box{padding:34px}}

javascript:
const $=id=>document.getElementById(id);
function calc(){const c=+$('cpu').value,r=+$('ram').value,s=+$('ssd').value;
$('ocpu').textContent=c;$('oram').textContent=r;$('ossd').textContent=s;
const m=Math.round(c*4+r*2.5+s*0.05);$('price').textContent='$'+m;$('hr').textContent='or $'+(m/730).toFixed(3)+' per hour'}
['cpu','ram','ssd'].forEach(i=>$(i).addEventListener('input',calc));calc();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
